    id: "c17", perspectiva: "Cognitivo-Conductual", subfamilia: "Terapias de reestructuración cognitiva", fundamentosTeoricos: ["wolpe", "ellis", "beck", "kanfer", "pavlov-watson", "thorndikeskinner", "neisser"],
    nombre: "Reestructuración Racional Sistemática",
